import app from 'flarum/forum/app';

/** The page, the queue, the profile list and the form: one chunk, fetched the first time any is needed. */
export const ui = () => import(/* webpackChunkName: 'forum/components', webpackMode: 'lazy-once' */ './components');
/** "Share your experience": the form, or the log-in dialog for a guest. */
export function openShare(prefill = {}) {
  if (!app.session.user) {
    app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
    return;
  }
  ui().then(({
    ShareModal
  }) => app.modal.show(ShareModal, {
    ...prefill
  }));
}