import app from 'flarum/forum/app';
import { api, onChange } from '../util';
/*
 * One answer per query, shared by every widget that asks it: a carousel in Bespoke's hero and
 * a wall in Page Builder with the same settings cost one request. Module level, because Bespoke
 * re-creates its widgets on every redraw (a fetch in oninit would loop).
 */
const lists = new Map();
const summaries = new Map();
const STALE = 5 * 60_000;
function get(map, key, load, empty) {
  let entry = map.get(key);
  if (!entry) map.set(key, entry = {
    value: null,
    busy: false,
    at: 0
  });
  if (!entry.busy && (!entry.at || Date.now() - entry.at > STALE)) {
    const e = entry;
    e.busy = true;
    load().then(value => e.value = value)
    // Keep what was shown; empty only if there never was anything.
    .catch(() => e.value ??= empty).finally(() => {
      e.busy = false;
      e.at = Date.now();
      m.redraw();
    });
  }
  return entry.value;
}

/** Live testimonials for these filters (`filter[...]` keys without the prefix), or null while loading. */
export function list(filters, limit) {
  const params = {
    filter: filters,
    page: {
      limit
    }
  };
  return get(lists, JSON.stringify(params), () => app.store.find('testimonials', params).then(rows => [...rows]), []);
}
export function summary(params) {
  return get(summaries, JSON.stringify(params), () => app.request({
    method: 'GET',
    url: api('testimonials-summary'),
    params,
    errorHandler: () => {}
  }), {
    count: 0,
    rated: 0,
    average: null,
    spread: {},
    aspects: []
  });
}

// A save, an approval or a take-down: everything is asked again the next time it's drawn.
onChange(() => {
  lists.forEach(entry => entry.at = 0);
  summaries.forEach(entry => entry.at = 0);
});
flarum.reg.add('ernestdefoe-testimonials', 'forum/widgets/data', { list: list,summary: summary, });