import Model from 'flarum/common/Model';
/** A testimonial as TestimonialResource serializes it. The author block already follows the byline. */
export default class Testimonial extends Model {
  headline = Model.attribute('headline');
  body = Model.attribute('body');
  rating = Model.attribute('rating');
  byline = Model.attribute('byline');
  source = Model.attribute('source');
  isFeatured = Model.attribute('isFeatured');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  author = Model.attribute('author');
  subject = Model.attribute('subject');
  aspects = Model.attribute('aspects');
  status = Model.attribute('status');
  declineReason = Model.attribute('declineReason');
  consentExternal = Model.attribute('consentExternal');
  hiddenByAuthor = Model.attribute('hiddenByAuthor');
  editedByStaffAt = Model.attribute('editedByStaffAt', Model.transformDate);
  removedAt = Model.attribute('removedAt', Model.transformDate);
  canEdit = Model.attribute('canEdit');
  canEditWording = Model.attribute('canEditWording');
  canRemove = Model.attribute('canRemove');
  canRestore = Model.attribute('canRestore');
  canHide = Model.attribute('canHide');
  canModerate = Model.attribute('canModerate');
}